-- Preserve action IDs and both legislative/financial evidence FK links.
CREATE TABLE report_actions_next(id TEXT PRIMARY KEY,report_id TEXT NOT NULL REFERENCES national_reports(id),ordinal INTEGER NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('movement_order','movement_arrival','record_event','legislation','financial','battle')),payload_json TEXT NOT NULL,line_start INTEGER NOT NULL,line_end INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','applied','rejected')),target_id TEXT,UNIQUE(report_id,ordinal));
INSERT INTO report_actions_next SELECT * FROM report_actions;
CREATE TABLE bill_event_evidence_next(event_id TEXT NOT NULL REFERENCES bill_events(id),source_id TEXT NOT NULL REFERENCES sources(id),line_start INTEGER NOT NULL,line_end INTEGER NOT NULL,report_action_id TEXT NOT NULL UNIQUE REFERENCES report_actions_next(id),PRIMARY KEY(event_id,report_action_id));
INSERT INTO bill_event_evidence_next SELECT * FROM bill_event_evidence;
CREATE TABLE ledger_report_evidence_next(ledger_id TEXT NOT NULL REFERENCES ledger_report_records(ledger_id),source_id TEXT NOT NULL REFERENCES sources(id),line_start INTEGER NOT NULL,line_end INTEGER NOT NULL,report_action_id TEXT NOT NULL UNIQUE REFERENCES report_actions_next(id),PRIMARY KEY(ledger_id,report_action_id));
INSERT INTO ledger_report_evidence_next SELECT * FROM ledger_report_evidence;
DROP TABLE ledger_report_evidence;
DROP TABLE bill_event_evidence;
DROP TABLE report_actions;
ALTER TABLE report_actions_next RENAME TO report_actions;
ALTER TABLE bill_event_evidence_next RENAME TO bill_event_evidence;
ALTER TABLE ledger_report_evidence_next RENAME TO ledger_report_evidence;
CREATE TRIGGER bill_evidence_no_update BEFORE UPDATE ON bill_event_evidence BEGIN SELECT RAISE(ABORT,'Legislative evidence is append-only'); END;
CREATE TRIGGER bill_evidence_no_delete BEFORE DELETE ON bill_event_evidence BEGIN SELECT RAISE(ABORT,'Legislative evidence is append-only'); END;
CREATE TRIGGER ledger_report_evidence_no_update BEFORE UPDATE ON ledger_report_evidence BEGIN SELECT RAISE(ABORT,'Financial evidence is append-only'); END;
CREATE TRIGGER ledger_report_evidence_no_delete BEFORE DELETE ON ledger_report_evidence BEGIN SELECT RAISE(ABORT,'Financial evidence is append-only'); END;
CREATE TABLE battle_report_records(id TEXT PRIMARY KEY,battle_id TEXT NOT NULL REFERENCES battles(id),reference TEXT NOT NULL,signature TEXT NOT NULL,date_json TEXT NOT NULL,location TEXT,belligerents TEXT,outcome TEXT,recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(battle_id,reference));
CREATE TABLE battle_report_evidence(record_id TEXT NOT NULL REFERENCES battle_report_records(id),source_id TEXT NOT NULL REFERENCES sources(id),line_start INTEGER NOT NULL,line_end INTEGER NOT NULL,report_action_id TEXT NOT NULL UNIQUE REFERENCES report_actions(id),PRIMARY KEY(record_id,report_action_id));
CREATE TABLE battle_report_participants(id TEXT PRIMARY KEY,record_id TEXT NOT NULL REFERENCES battle_report_records(id),unit_id TEXT REFERENCES units(id),name TEXT,side TEXT);
CREATE TABLE battle_report_casualties(casualty_id TEXT PRIMARY KEY REFERENCES casualties(id),record_id TEXT NOT NULL REFERENCES battle_report_records(id),participant_id TEXT NOT NULL REFERENCES battle_report_participants(id));
CREATE TABLE battle_report_losses(id TEXT PRIMARY KEY,record_id TEXT NOT NULL REFERENCES battle_report_records(id),unit_id TEXT REFERENCES units(id),equipment TEXT NOT NULL,count INTEGER CHECK(count>=0),state TEXT NOT NULL CHECK(state IN ('lost','damaged','unknown')),asset_id TEXT REFERENCES assets(id),UNIQUE(record_id,asset_id));
CREATE TABLE battle_asset_effects(loss_id TEXT PRIMARY KEY REFERENCES battle_report_losses(id),asset_id TEXT NOT NULL REFERENCES assets(id),date TEXT NOT NULL,before_state TEXT NOT NULL,after_state TEXT NOT NULL,assignments_before TEXT NOT NULL);
CREATE TRIGGER battle_report_records_no_update BEFORE UPDATE ON battle_report_records BEGIN SELECT RAISE(ABORT,'After-action history is append-only'); END;
CREATE TRIGGER battle_report_records_no_delete BEFORE DELETE ON battle_report_records BEGIN SELECT RAISE(ABORT,'After-action history is append-only'); END;
CREATE TRIGGER battle_report_evidence_no_update BEFORE UPDATE ON battle_report_evidence BEGIN SELECT RAISE(ABORT,'After-action history is append-only'); END;
CREATE TRIGGER battle_report_evidence_no_delete BEFORE DELETE ON battle_report_evidence BEGIN SELECT RAISE(ABORT,'After-action history is append-only'); END;
CREATE TRIGGER battle_report_participants_no_update BEFORE UPDATE ON battle_report_participants BEGIN SELECT RAISE(ABORT,'After-action history is append-only'); END;
CREATE TRIGGER battle_report_participants_no_delete BEFORE DELETE ON battle_report_participants BEGIN SELECT RAISE(ABORT,'After-action history is append-only'); END;
CREATE TRIGGER battle_report_casualties_no_update BEFORE UPDATE ON battle_report_casualties BEGIN SELECT RAISE(ABORT,'After-action history is append-only'); END;
CREATE TRIGGER battle_report_casualties_no_delete BEFORE DELETE ON battle_report_casualties BEGIN SELECT RAISE(ABORT,'After-action history is append-only'); END;
CREATE TRIGGER battle_report_losses_no_update BEFORE UPDATE ON battle_report_losses BEGIN SELECT RAISE(ABORT,'After-action history is append-only'); END;
CREATE TRIGGER battle_report_losses_no_delete BEFORE DELETE ON battle_report_losses BEGIN SELECT RAISE(ABORT,'After-action history is append-only'); END;
CREATE TRIGGER battle_asset_effects_no_update BEFORE UPDATE ON battle_asset_effects BEGIN SELECT RAISE(ABORT,'After-action history is append-only'); END;
CREATE TRIGGER battle_asset_effects_no_delete BEFORE DELETE ON battle_asset_effects BEGIN SELECT RAISE(ABORT,'After-action history is append-only'); END;
